import type { ComponentRegistry } from "./registry";
import type { EdgeDoc, GraphDoc } from "./graph";
import { createRng, hashSeed } from "./rng";
import { rpsAt, type Fault, type Scenario } from "./scenario";
import type { ActiveFault, ConfigRecord, EdgeFeedback, Inflow, Outflow, SimEvent, TickContext } from "./types";
import { Histogram } from "../metrics/histogram";

export interface Snapshot {
  time: number;
  global: {
    offeredRps: number;
    /** Extra load generated by client retries (not part of offered). */
    retryRps: number;
    /** Share of completed requests that were duplicates of work already done. */
    duplicateRate: number;
    throughputRps: number;
    droppedRps: number;
    errorRate: number;
    p50: number;
    p95: number;
    p99: number;
    costPerHour: number;
  };
  nodes: Record<string, Record<string, number>>;
  edges: Record<string, { rps: number; latencyMs: number }>;
  /** Node ids currently killed by a fault. */
  down: string[];
  /** Events raised since the previous snapshot. */
  events: SimEvent[];
}

interface NodeRuntime {
  id: string;
  kind: string;
  state: unknown;
  inbound: Inflow[];
  outEdges: Record<string, EdgeDoc[]>;
}

/**
 * Fixed-step flow simulation. Each tick, every node consumes what arrived last tick and
 * emits flows along its edges; so cycles are fine and node order never matters.
 * Outflow on a port with no edge counts as completed (it left the system).
 */
export class Simulation {
  time = 0;
  private nodes: NodeRuntime[] = [];
  private nodeById = new Map<string, NodeRuntime>();
  private dt: number;
  private hist = new Histogram();
  private windowOffered = 0;
  private windowCompleted = 0;
  private windowDropped = 0;
  private windowRecovered = 0;
  private windowRetries = 0;
  private windowDup = 0;
  private fbCur = new Map<string, EdgeFeedback>();
  private fbNext = new Map<string, EdgeFeedback>();
  private timeoutFailedNow = 0;
  private parentOf = new Map<string, string>();
  private windowEdge = new Map<string, number>();
  private windowEdgeLat = new Map<string, number>();
  private windowEvents: SimEvent[] = [];
  private windowTime = 0;
  private edgesById = new Map<string, EdgeDoc>();
  private doc: GraphDoc = { nodes: [], edges: [] };
  private docNode = new Map<string, GraphDoc["nodes"][number]>();
  private faultsByTarget = new Map<string, Fault[]>();
  private rngs = new Map<string, ReturnType<typeof createRng>>();

  constructor(
    private reg: ComponentRegistry,
    doc: GraphDoc,
    private scenario: Scenario,
  ) {
    this.dt = (scenario.tickMs ?? 10) / 1000;
    const ids = new Set<string>();
    for (const n of doc.nodes) { if (ids.has(n.id)) throw new Error(`Duplicate node id "${n.id}"`); ids.add(n.id); }
    for (const e of doc.edges) this.edgesById.set(e.id, e);
    // work on a copy with defaults merged, so older saved designs missing new fields still run
    this.doc = { nodes: doc.nodes.map((n) => ({ ...n, config: { ...(reg.get(n.kind)?.defaults ?? {}), ...n.config } })), edges: doc.edges };
    for (const n of this.doc.nodes) { this.docNode.set(n.id, n); if (n.parentId) this.parentOf.set(n.id, n.parentId); }
    for (const f of scenario.faults) {
      const targets = f.target.startsWith("kind:") ? this.doc.nodes.filter((n) => n.kind === f.target.slice(5)).map((n) => n.id) : [f.target];
      for (const t of targets) { let l = this.faultsByTarget.get(t); if (!l) this.faultsByTarget.set(t, (l = [])); l.push(f); }
    }
    for (const n of this.doc.nodes) {
      const def = reg.get(n.kind);
      if (!def) throw new Error(`Unknown component "${n.kind}"`);
      const outEdges: Record<string, EdgeDoc[]> = {};
      for (const e of doc.edges) if (e.from === n.id) (outEdges[e.fromPort] ??= []).push(e);
      const rt: NodeRuntime = { id: n.id, kind: n.kind, state: def.init(n.config), inbound: [], outEdges };
      this.nodes.push(rt);
      this.nodeById.set(n.id, rt);
      this.rngs.set(n.id, createRng(hashSeed(scenario.seed, n.id)));
    }
  }

  /** Apply edited configs without resetting state (live tuning while running). */
  setConfigs(configs: Record<string, ConfigRecord>) {
    for (const n of this.doc.nodes) if (configs[n.id]) n.config = { ...(this.reg.get(n.kind)?.defaults ?? {}), ...configs[n.id]! };
  }

  get done() { return this.time >= this.scenario.durationSec; }

  private faultsFor(target: string): ActiveFault[] {
    const out: ActiveFault[] = [];
    for (const f of this.faultsByTarget.get(target) ?? []) {
      const active = this.time >= f.atSec && (f.untilSec === undefined || this.time < f.untilSec);
      const instant = f.untilSec === undefined && this.time >= f.atSec && this.time < f.atSec + this.dt;
      if (active || instant) out.push({ kind: f.kind, params: f.params ?? {}, justStarted: this.time >= f.atSec && this.time < f.atSec + this.dt });
    }
    return out;
  }

  /** A node is down if it, or the region/zone boundary containing it, has a kill-node fault active. */
  private isDown(nodeId: string): boolean {
    const own = this.faultsFor(nodeId).some((f) => f.kind === "kill-node");
    if (own) return true;
    if (this.regionOutage(nodeId)) return !this.reg.get(this.docNode.get(nodeId)?.kind ?? "")?.handlesRegionOutage;
    return false;
  }
  /** True if a boundary containing this node has a kill-node fault active. */
  private regionOutage(nodeId: string): boolean {
    for (let id = this.parentOf.get(nodeId), hops = 0; id && hops < 8; id = this.parentOf.get(id), hops++)
      if (this.faultsFor(id).some((f) => f.kind === "kill-node")) return true;
    return false;
  }

  private fb(edgeId: string): EdgeFeedback { let f = this.fbNext.get(edgeId); if (!f) this.fbNext.set(edgeId, (f = { sent: 0, failed: 0, timedOut: 0 })); return f; }

  /** Report failed items to the edges that fed this node, in proportion to what each delivered. */
  private attribute(inbound: Inflow[], failed: number, timedOut: number) {
    if (!(failed > 0)) return;
    const total = inbound.reduce((a, f) => a + f.count, 0);
    if (!(total > 0)) return;
    for (const f of inbound) {
      const share = f.count / total;
      const fb = this.fb(f.edgeId);
      fb.failed += failed * share;
      fb.timedOut += timedOut * share;
    }
  }

  step() {
    const rps = rpsAt(this.scenario.traffic, this.time, this.scenario.durationSec);
    const next = new Map<string, Inflow[]>();
    const push = (id: string, f: Inflow) => { let l = next.get(id); if (!l) next.set(id, (l = [])); l.push(f); };

    for (const n of this.nodes) {
      const def = this.reg.get(n.kind)!;
      const doc = this.docNode.get(n.id)!;
      const faults = this.faultsFor(n.id);
      if (this.regionOutage(n.id) && def.handlesRegionOutage) {
        let started = false;
        for (let id = this.parentOf.get(n.id); id; id = this.parentOf.get(id)) for (const f of this.faultsFor(id)) if (f.kind === "kill-node" && f.justStarted) started = true;
        faults.push({ kind: "region-outage", params: {}, justStarted: started });
      }

      if (this.isDown(n.id)) {
        const lost = n.inbound.reduce((s, f) => s + f.count, 0);
        this.windowDropped += lost;
        this.attribute(n.inbound, lost, 0);
        if (faults.some((f) => f.justStarted && f.kind === "kill-node"))
          this.windowEvents.push({ time: this.time, nodeId: n.id, severity: "error", kind: "node-down", message: `${doc.label ?? def.name} killed` });
        n.inbound = [];
        continue;
      }

      const ctx: TickContext = {
        dt: this.dt,
        time: this.time,
        rps,
        regionRttMs: this.scenario.regionRttMs ?? 0,
        rng: this.rngs.get(n.id)!,
        nodeId: n.id,
        outEdges: Object.fromEntries(Object.entries(n.outEdges).map(([p, es]) => [p, es.map((e) => e.id)])),
        isEdgeTargetDown: (edgeId) => {
          const e = this.edgesById.get(edgeId);
          return !!e && this.isDown(e.to);
        },
        feedback: (edgeId) => this.fbCur.get(edgeId) ?? { sent: 0, failed: 0, timedOut: 0 },
        faults,
      };
      const inbound = n.inbound;
      const res = def.tick(ctx, doc.config, n.state, inbound);
      n.state = res.state;
      n.inbound = [];
      this.windowDropped += res.dropped;
      for (const ev of res.events) this.windowEvents.push(ev);
      const dupIn = inbound.reduce((a, f) => a + (f.dupFraction ?? 0) * f.count, 0) / Math.max(1e-12, inbound.reduce((a, f) => a + f.count, 0));
      this.timeoutFailedNow = 0;
      for (const o of res.outbound) this.route(n, o, push, Number.isFinite(dupIn) ? dupIn : 0);
      // Failures seen on this node's out-edges last tick flow back to whoever fed it, unless it handled them.
      let outFailed = 0, outTimedOut = 0;
      if (!def.asyncBoundary) for (const es of Object.values(n.outEdges)) for (const e of es) { const f = this.fbCur.get(e.id); if (f) { outFailed += f.failed; outTimedOut += f.timedOut; } }
      const recovered = Math.max(0, res.recovered ?? 0);
      this.windowRecovered += recovered;
      const keep = outFailed > 0 ? Math.max(0, outFailed - recovered) / outFailed : 0;
      // late completions at a queue/log are the consumer side's problem: don't blame (and retry) already-acknowledged producers
      const lateNow = def.asyncBoundary ? 0 : this.timeoutFailedNow;
      this.attribute(inbound, res.dropped + lateNow + outFailed * keep, outTimedOut * keep + lateNow);
    }

    for (const n of this.nodes) n.inbound = next.get(n.id) ?? [];
    this.fbCur = this.fbNext;
    this.fbNext = new Map();
    this.time += this.dt;
    this.windowTime += this.dt;
  }

  private route(n: NodeRuntime, o: Outflow, push: (id: string, f: Inflow) => void, dupIn: number) {
    if (!(o.count > 0) || !Number.isFinite(o.count)) return; // also drops NaN
    if (!Number.isFinite(o.latencyMs)) o = { ...o, latencyMs: 0 };
    const edges = o.edgeId ? [this.edgesById.get(o.edgeId)].filter((e): e is EdgeDoc => !!e) : n.outEdges[o.port] ?? [];
    const dup = Math.min(1, Math.max(0, o.dupFraction ?? dupIn));
    if (n.kind === "client") { const r = Math.min(o.count, Math.max(0, o.retryCount ?? 0)); this.windowOffered += o.count - r; this.windowRetries += r; }
    if (edges.length === 0) {
      // a dead end only completes the request if this is a declared terminal port or a service endpoint
      const def = this.reg.get(n.kind);
      const terminal = def?.sink || def?.ports.find((p) => p.id === o.port)?.hidden;
      if (!terminal) { this.windowDropped += o.count; return; }
      const limit = this.scenario.timeoutMs;
      if (limit !== undefined && !o.silent && o.latencyMs > limit) { // finished too late for the caller
        this.windowDropped += o.count;
        this.timeoutFailedNow += o.count;
        return;
      }
      this.windowCompleted += o.count;
      this.windowDup += o.count * dup;
      if (!o.silent) this.hist.add(o.latencyMs, o.count);
      return;
    }
    const share = o.edgeId ? o.count : o.count / edges.length;
    for (const e of edges) {
      let count = share;
      if (e.maxRps !== undefined) {
        const cap = Math.max(0, e.maxRps) * this.dt;
        if (count > cap) { this.windowDropped += count - cap; this.fb(e.id).failed += count - cap; this.fb(e.id).sent += count - cap; count = cap; }
      }
      this.fb(e.id).sent += count;
      let extra = 0;
      for (const f of this.faultsByTarget.get(e.id) ?? []) if (f.kind === "edge-latency" && this.time >= f.atSec && (f.untilSec === undefined || this.time < f.untilSec)) extra += Number(f.params?.addMs ?? 0);
      if (this.scenario.regionRttMs && (this.parentOf.get(e.from) ?? "") !== (this.parentOf.get(e.to) ?? "") && this.parentOf.get(e.from) && this.parentOf.get(e.to)) extra += this.scenario.regionRttMs;
      this.windowEdge.set(e.id, (this.windowEdge.get(e.id) ?? 0) + count);
      this.windowEdgeLat.set(e.id, (this.windowEdgeLat.get(e.id) ?? 0) + count * (o.latencyMs + (e.latencyMs ?? 0) + extra));
      push(e.to, { port: e.toPort, edgeId: e.id, protocol: e.protocol, count, latencyMs: o.latencyMs + (e.latencyMs ?? 0) + extra, readFraction: o.readFraction, dupFraction: dup });
    }
  }

  /** Read aggregated metrics since the last snapshot, then reset the window. */
  snapshot(): Snapshot {
    const w = Math.max(this.windowTime, this.dt);
    const dropped = Math.max(0, this.windowDropped - this.windowRecovered);
    const finished = this.windowCompleted + dropped;
    const nodes: Snapshot["nodes"] = {};
    let cost = 0;
    for (const n of this.nodes) {
      const def = this.reg.get(n.kind)!;
      const cfg = this.docNode.get(n.id)!.config;
      nodes[n.id] = def.sample(cfg, n.state);
      cost += def.costPerHour?.(cfg, n.state) ?? 0;
    }
    const edges: Snapshot["edges"] = {};
    for (const e of this.doc.edges) { const n = this.windowEdge.get(e.id) ?? 0; edges[e.id] = { rps: n / w, latencyMs: n > 0 ? (this.windowEdgeLat.get(e.id) ?? 0) / n : 0 }; }
    const snap: Snapshot = {
      time: this.time,
      global: {
        offeredRps: this.windowOffered / w,
        retryRps: this.windowRetries / w,
        duplicateRate: this.windowCompleted > 0 ? this.windowDup / this.windowCompleted : 0,
        throughputRps: this.windowCompleted / w,
        droppedRps: dropped / w,
        errorRate: finished > 0 ? dropped / finished : 0,
        p50: this.hist.percentile(0.5),
        p95: this.hist.percentile(0.95),
        p99: this.hist.percentile(0.99),
        costPerHour: cost,
      },
      nodes, edges, events: this.windowEvents,
      down: this.nodes.filter((n) => this.isDown(n.id)).map((n) => n.id),
    };
    this.windowOffered = this.windowCompleted = this.windowDropped = this.windowTime = this.windowRecovered = this.windowRetries = this.windowDup = 0;
    this.windowEdge.clear();
    this.windowEdgeLat.clear();
    this.windowEvents = [];
    this.hist.reset();
    return snap;
  }

  /** Run to completion (or `until`), sampling every `sampleMs`. For tests, CLI and challenge grading. */
  run(sampleMs = 100, until = this.scenario.durationSec): Snapshot[] {
    const out: Snapshot[] = [];
    const every = Math.max(1, Math.round(sampleMs / (this.dt * 1000)));
    let i = 0;
    while (this.time < until) {
      this.step();
      if (++i % every === 0) out.push(this.snapshot());
    }
    return out;
  }
}
